#!/usr/bin/env python3
"""PCQI_mk_cwmc.py: PRVEq_CurrentWideMulCanonical_j2.lean = fresh block generated by PCQI_gen_equalities.py (gate CurrentWideMulCanonical)
plus callee equalities against the compiled AspisR1Qm31ArithmeticProbe constants (the gate's abbrevs point there) and the three target equalities."""
import re,sys
sys.dont_write_bytecode=True
T='CurrentWideMulCanonical_j4'
g=open('PRVEq_CurrentWideMulCanonical_j1.lean').read()
head=g[:g.index('end AspisR1CurrentWideMul')+len('end AspisR1CurrentWideMul')]
head=head.replace('PRVFresh_CurrentWideMulCanonical_j1','PRVFresh_'+T).replace('import CurrentWideMulCanonical','import CurrentWideMulCanonical\nimport AspisR1Qm31ArithmeticProbe.Funs')
F='AspisR1CurrentWideMul.PRVFresh_'+T;PR='AspisR1Qm31ArithmeticProbe';GA='AspisR1CurrentWideMul'
# (fresh name, probe name, callee theorem names)
chain=[('field.P','field.P',[]),('field.M31.add','field.M31.add',['field.P']),('field.M31.double','field.M31.double',['field.M31.add']),
 ('field.M31.sub','field.M31.sub',['field.P']),('field.mul_by_r','field.mul_by_r',['field.M31.add','field.M31.sub','field.M31.double']),
 ('field.reduce_u64','field.reduce_u64',['field.P']),('field.M31.reduce_u64','field.M31.reduce_u64',['field.reduce_u64']),
 ('field.M31.mul','field.M31.mul',['field.reduce_u64']),
 ('field.CM31.mul','field.CM31.mul',['field.M31.add','field.M31.sub','field.M31.mul','field.M31.reduce_u64']),
 ('field.CM31.sub','field.CM31.sub',['field.M31.sub']),('field.CM31.add','field.CM31.add',['field.M31.add']),
 ('field.QM31.mul','field.QM31.mul',['field.CM31.mul','field.CM31.add','field.CM31.sub','field.mul_by_r'])]
out=[head,'']
def th(name,lhs,rhs,deps,note):
    s=f"theorem PRVEq.{T}.{name} : @{lhs} = @{rhs} := by\n  (trace \"PRV-S2 {name}\"; delta {lhs} {rhs}; try simp only [{', '.join(deps)}]; try rfl; done)\n#print axioms PRVEq.{T}.{name}\n"
    return s
for fn,pn,deps in chain:
    out.append(th('Probe.'+fn,f'{F}.{fn}',f'{PR}.{pn}',[f'PRVEq.{T}.Probe.{d}' for d in deps],''))
# QM31.add is also a callee of QM31.mul? no; but WideExact.mul uses it
out.append(th('Probe.field.QM31.add',f'{F}.field.QM31.add',f'{PR}.field.QM31.add',[f'PRVEq.{T}.Probe.field.CM31.add'],''))
# targets
out.append(th('field.QM31.sub',f'{F}.field.QM31.sub',f'{GA}.field.QM31.sub',[f'PRVEq.{T}.Probe.field.CM31.sub'],''))
out.append(th('field.wide_exact.mul_u',f'{F}.field.wide_exact.mul_u',f'{GA}.field.wide_exact.mul_u',[f'PRVEq.{T}.Probe.field.mul_by_r'],''))
out.append(th('field.wide_exact.WideExact.mul',f'{F}.field.wide_exact.WideExact.mul',f'{GA}.field.wide_exact.WideExact.mul',
 [f'PRVEq.{T}.Probe.field.QM31.mul',f'PRVEq.{T}.Probe.field.QM31.add',f'PRVEq.{T}.field.QM31.sub',f'PRVEq.{T}.field.wide_exact.mul_u'],''))
open(f'PRVEq_{T}.lean','w').write('\n'.join(out))
